package ds454.locomotive.steamservice.steamapi.model;

import java.util.List;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;

// Generated by Claude

@JsonIgnoreProperties(ignoreUnknown = true)
public record AchievementsForAppId(Game game) {

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record Game(AvailableGameStats availableGameStats) {
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record AvailableGameStats(List<Achievement> achievements) {

        // Drop achievements with a missing or blank description
        // (Steam leaves description empty/absent on some hidden achievements).
        public AvailableGameStats {
            achievements = achievements == null
                    ? List.of()
                    : achievements.stream()
                            .filter(a -> a.description() != null && !a.description().isBlank())
                            .filter(a -> a.isValid())
                            .toList();
        }
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record Achievement(String name, String displayName, String description) {
        public boolean isValid() {
            if (name() == null || name().isBlank()) return false;
            if (displayName() == null || displayName().isBlank()) return false;
            if (description() == null || description().isBlank()) return false;

            return true;
        }
    }
}